import {LoadingTestsManager} from 'loadingtests/LoadingTestsManager';

import {Component} from '@angular/core';
import {AddPlayerRemote} from 'loadingtests/commands/AddPlayerRemote';
import {AddStatRemote} from 'loadingtests/commands/AddStatRemote';
import {Reset} from 'loadingtests/commands/Reset';

import {
  config,
  PlayerStatListControlsComponent
} from 'test_load_inner/PlayerStatListControlsComponent';
import {CommandManager} from "@umlp/common";

/* generated by template umlp.gui2ts.TSAnnotationDirective*/
@Component({
  standalone: true,
  imports: [...config.imports],
  selector: config.selector,
  templateUrl: config.templateUrl,
})
export class PlayerStatListControls extends PlayerStatListControlsComponent {

  public override addPlayer_Local(): () => void {
    return () => {
      LoadingTestsManager.getGameSure(this.getGemIdForNav()).then(
          (g) => {
            LoadingTestsManager.playerBuilder().then(p => {
              g.addPlayer2(p.name("From Local")
                  .isActive(true)
                  .points(0)
                  .build())
            })
          }
      )
    };
  }

  public override addStat_Local(): () => void {
    return () => {
      LoadingTestsManager.getGameSure(this.getGemIdForNav()).then(
          (g) => {
            const p = g.getPlayer1(0);
            LoadingTestsManager.playerStatBuilder().then(s => {
              p.addPlayerStat2(s.statID("local stat of " + p.getName()).build())
            })
          }
      )
    };
  }

  public override addPlayer_Remote(): () => void {
    return () => {
      CommandManager.executeCommand(new AddPlayerRemote(this._gemIdForNav));
    };
  }

  public override addStat_Remote(): () => void {
    return () => {
      CommandManager.executeCommand(new AddStatRemote(this._gemIdForNav));
    };
  }

  public override reset(): () => void {
    return () => {
      CommandManager.executeCommand(new Reset(this._gemIdForNav));
    };
  }

}

